     "        acts, labels = acts.to(device), labels.to(device)",
     "        probe = LRProbe(acts.shape[-1]).to(device)",
     "        ",
     "        opt = t.optim.AdamW(probe.parameters(), lr=lr, weight_decay=weight_decay)",
     "        for _ in range(epochs):",
